import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 24 章 内置技能库（一）：图像与视频生成（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第24章 内置技能库（一）：图像与视频生成（易懂版）.md","filePath":"easy/第24章 内置技能库（一）：图像与视频生成（易懂版）.md"}'),d={name:"easy/第24章 内置技能库（一）：图像与视频生成（易懂版）.md"};function l(n,t,s,i,h,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-24-章-内置技能库-一-图像与视频生成-易懂版" tabindex="-1">第 24 章 内置技能库（一）：图像与视频生成（易懂版） <a class="header-anchor" href="#第-24-章-内置技能库-一-图像与视频生成-易懂版" aria-label="Permalink to &quot;第 24 章 内置技能库（一）：图像与视频生成（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 <a href="./../bluebook/第五篇 平台能力全景/第 24 章 内置技能库（一）：图像与视频生成.html">第 24 章 内置技能库（一）：图像与视频生成（完整版）</a>。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>我能出图、也能出片——但你得把&quot;要什么画面&quot;说清楚，视频还得先看脚本再开拍。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>出图就像<strong>下单拍照</strong>：你得告诉摄影师，拍什么、什么风格、多大画幅、画面里要不要写字。 出片不一样，像<strong>拍广告</strong>：得先有分镜脚本，甲方点头了，才开机器——不然拍完才发现方向错了，白烧钱。</p><h2 id="说清-一幅图-的六件事" tabindex="-1">说清&quot;一幅图&quot;的六件事 <a class="header-anchor" href="#说清-一幅图-的六件事" aria-label="Permalink to &quot;说清&quot;一幅图&quot;的六件事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>大白话</th><th>例子</th></tr></thead><tbody><tr><td>用途</td><td>用在哪</td><td>公众号头图</td></tr><tr><td>主题</td><td>画什么</td><td>一杯冒热气的咖啡</td></tr><tr><td>风格</td><td>什么味道</td><td>简约、暖色、日系</td></tr><tr><td>尺寸</td><td>多大</td><td>横版 1792×1024</td></tr><tr><td>文字</td><td>要不要写字</td><td>画面写&quot;早安&quot;两字</td></tr><tr><td>验收</td><td>你最在意啥</td><td>字要清楚，别糊</td></tr></tbody></table><h2 id="视频有个-确认门-很重要" tabindex="-1">视频有个&quot;确认门&quot;（很重要） <a class="header-anchor" href="#视频有个-确认门-很重要" aria-label="Permalink to &quot;视频有个&quot;确认门&quot;（很重要）&quot;">​</a></h2><p><strong>先脚本 → 你确认 → 再生成。</strong> 三步不能跳。</p><p>因为视频又贵又慢，方向错了最亏。脚本里说清：几个镜头、每个镜头画面、时长、配乐风格、字幕文案。</p><h2 id="一句好用的口令" tabindex="-1">一句好用的口令 <a class="header-anchor" href="#一句好用的口令" aria-label="Permalink to &quot;一句好用的口令&quot;">​</a></h2><blockquote><p>&quot;帮我把【主题】做成一张【用途】图，风格【风格】，尺寸【尺寸】，画面文字是【文案】，先给我三个方案我挑一个。&quot;</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 一句话就要成片——<strong>先要脚本/方案，挑完再做</strong>；</li><li>❌ 图上的字让它自由发挥——<strong>文字必须逐字给出</strong>；</li><li>❌ 只说&quot;好看点&quot;——<strong>&quot;好看&quot;没法执行，要给风格和验收标准</strong>；</li><li>❌ 视频不确认就生成——<strong>浪费时间和额度</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>图片靠&quot;六要素&quot;讲清楚；视频靠&quot;先脚本、后开拍&quot;。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>翻出你手机里最近想做的那个封面图，试着用六个要素各写一句——<strong>能写全，就说明你会下这个单了。</strong></p><p>👉 [下一章：内置技能库（二），文档、表格与演示（易懂版）](第25章 内置技能库（二）：文档、表格与演示（易懂版）.md)</p>',20)])])}const c=a(d,[["render",l]]);export{q as __pageData,c as default};
